const { url, events, secret, contentType, active } = $.input;
if (!url) throw new Error('url is required');
if (!url.startsWith('https://')) throw new Error('Webhook URL must use HTTPS');

const config = {
  url,
  content_type: contentType || 'json',
  insecure_ssl: '0'
};
if (secret) config.secret = secret;

const payload = {
  name: 'web',
  active: active !== false,
  events: events && events.length > 0 ? events : ['push'],
  config
};

return { payload };
